import itertools

def solve_for_n_with_sets(n):
    n_sq = n * n
    results = []
    for X in itertools.combinations(range(n_sq), n):
        if X[0] != 0: continue
        Y = [1]
        current_sum_set = set(x + 1 for x in X)
        possible = True
        for k in range(1, n):
            missing = 1
            while missing in current_sum_set:
                missing += 1
            if missing > n_sq:
                possible = False
                break
            y_k = missing
            for x in X:
                val = x + y_k
                if val < 1 or val > n_sq or val in current_sum_set:
                    possible = False
                    break
            if not possible:
                break
            Y.append(y_k)
            for x in X:
                current_sum_set.add(x + y_k)
        if possible and len(current_sum_set) == n_sq:
            results.append((set(X), set(Y)))
    return results

for n in range(2, 5):
    print(f"n={n}: {solve_for_n_with_sets(n)}")

